import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/models/member.dart';
import '../../../data/repositories/group_repository.dart';
import '../../widgets/app_drawer.dart';
class MembersScreen extends StatefulWidget{const MembersScreen({super.key});@override State<MembersScreen> createState()=>_MembersScreenState();}
class _MembersScreenState extends State<MembersScreen>{String q=''; @override Widget build(BuildContext context){final repo=context.read<GroupRepository>();return Scaffold(appBar:AppBar(title:const Text('Members')),drawer:const AppDrawer(),floatingActionButton:FloatingActionButton(onPressed:()=>_edit(context,repo),child:const Icon(Icons.add)),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Search Members'),onChanged:(v)=>setState(()=>q=v.toLowerCase()))),Expanded(child:StreamBuilder(stream:repo.members(),builder:(c,s){final data=(s.data??[]).where((m)=>m.name.toLowerCase().contains(q)||m.phone.contains(q)).toList();return ListView(children:data.map((m)=>ListTile(leading:CircleAvatar(backgroundImage:m.photo.isEmpty?null:NetworkImage(m.photo),child:m.photo.isEmpty?Text(m.name.isEmpty?'?':m.name[0]):null),title:Text(m.name),subtitle:Text('${m.phone} • ${m.nationalId}'),onTap:()=>_edit(context,repo,m),trailing:IconButton(icon:const Icon(Icons.delete),onPressed:()=>repo.deleteMember(m.id)))).toList());}))]));} void _edit(BuildContext context,GroupRepository repo,[Member? m]){final name=TextEditingController(text:m?.name);final phone=TextEditingController(text:m?.phone);final nid=TextEditingController(text:m?.nationalId);final address=TextEditingController(text:m?.address);showDialog(context:context,builder:(_)=>AlertDialog(title:Text(m==null?'Add Member':'Edit Member'),content:SingleChildScrollView(child:Column(children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Name')),TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone Number')),TextField(controller:nid,decoration:const InputDecoration(labelText:'National ID')),TextField(controller:address,decoration:const InputDecoration(labelText:'Address'))])),actions:[FilledButton(onPressed:(){repo.saveMember(Member(id:m?.id??'',name:name.text,phone:phone.text,nationalId:nid.text,address:address.text,joinDate:m?.joinDate??DateTime.now()));Navigator.pop(context);},child:const Text('Save'))]));}}
